int _sysdate();char *months[] = {    "???", "Jan", "Feb", "Mar", "Apr", "May", "Jun",    "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"}; char *days[] = {	"Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat" };char *cdate() {	long time, date, tick;	short weekday;	register int year, month, day;		static char buffer[20];	_sysdate(0, &time, &date, &weekday, &tick);	year = date >> 16;	month = (date >> 8) & 0xFF;	day = date & 0xFF;	if (year && month && day && (weekday < 7))		sprintf(buffer,"%s %s %d",			days[weekday], months[month], day);	else		sprintf(buffer, "(unknown date)");	return(buffer);}			